typedef struct {
    int x;
    int y;
} Point;

void tryToMove(Point p) {
    p.x += 100;   // modifies the local copy only
}

int main(void) {
    Point origin = {0, 0};

    printPoint(origin);   // (0, 0)
    tryToMove(origin);
    printPoint(origin);   // still (0, 0) -- tryToMove only changed its own copy

    return 0;
}
